        DELETE FROM processed_resources WHERE project_id = OLD.project_id AND kind = 'tool-output' AND resource_id = OLD.tool_call_id; END;

DROP VIEW IF EXISTS embedding_sources;

CREATE VIEW IF NOT EXISTS embedding_sources AS SELECT s.*, v.revision,
    COALESCE((SELECT k.state FROM knowledge_release_state k WHERE k.project_id = s.project_id AND k.namespace = s.namespace AND k.record_id = s.record_id ORDER BY k.checked_at DESC, k.id LIMIT 1), '') AS release_state,
    COALESCE((SELECT k.confidence FROM knowledge_release_state k WHERE k.project_id = s.project_id AND k.namespace = s.namespace AND k.record_id = s.record_id ORDER BY k.checked_at DESC, k.id LIMIT 1), '') AS release_confidence
    FROM (SELECT project_id, 'session' AS type, 'sessions' AS namespace, session_id AS record_id,
  COALESCE(title, 'Session') AS title, COALESCE(title, '') || char(10) || summary AS text, NULL AS blob_key, CASE WHEN COALESCE(occurred_ended_at, ended_at) IS NULL THEN 'active' ELSE 'completed' END AS status,
  COALESCE(session_id, '') AS session_id, NULL AS prompt_id, COALESCE(occurred_started_at, started_at, first_received_at) AS created_at, '' AS observation_type
  FROM sessions WHERE summary IS NOT NULL AND trim(summary) <> '' UNION ALL SELECT project_id, 'spore' AS type, 'spores' AS namespace, id AS record_id,
  observation_type AS title, content || char(10) || COALESCE(context, '') AS text, NULL AS blob_key, status AS status,
  COALESCE(session_id, '') AS session_id, prompt_id AS prompt_id, created_at AS created_at, observation_type AS observation_type
  FROM spores WHERE status = 'active' UNION ALL SELECT project_id, 'plan' AS type, 'plans' AS namespace, plan_key AS record_id,
  COALESCE(title, 'Plan') AS title, COALESCE(title, '') || char(10) || COALESCE(content, '') AS text, blob_key AS blob_key, status AS status,
  COALESCE(session_id, '') AS session_id, prompt_id AS prompt_id, created_at AS created_at, '' AS observation_type
  FROM plans WHERE content IS NOT NULL OR (blob_key IS NOT NULL AND EXISTS (
  SELECT 1 FROM processed_resources pr WHERE pr.project_id = plans.project_id AND pr.kind = 'plan'
    AND pr.resource_id = plans.plan_key AND pr.blob_key = plans.blob_key AND pr.classification = 'processed')) UNION ALL SELECT project_id, 'skill' AS type, 'skill_records' AS namespace, id AS record_id,
  COALESCE(NULLIF(display_name, ''), name) AS title, name || char(10) || description AS text, NULL AS blob_key, status AS status,
  COALESCE(NULL, '') AS session_id, NULL AS prompt_id, created_at AS created_at, '' AS observation_type
  FROM skill_records WHERE status = 'active') s JOIN embedding_versions v ON v.project_id = s.project_id AND v.type = s.type AND v.record_id = s.record_id;

CREATE TRIGGER IF NOT EXISTS processed_resources_immutable BEFORE UPDATE ON processed_resources BEGIN
     SELECT RAISE(ABORT, 'processed reference classification is immutable'); END;

CREATE TRIGGER IF NOT EXISTS raw_resources_immutable BEFORE UPDATE ON raw_resources BEGIN
     SELECT RAISE(ABORT, 'raw reference ownership and classification are immutable'); END;

INSERT OR REPLACE INTO schema_meta (key, value) VALUES ('version', '70');
